package br.com.pacto.recrutamento.infra.templatevaga; import br.com.pacto.recrutamento.app.templatevaga.PerguntaTemplateVagaRepositorio; import br.com.pacto.recrutamento.core.entities.PerguntaTemplateVaga; import org.springframework.stereotype.Repository; import java.util.*; import java.util.stream.*; @Repository class PerguntaTemplateVagaJpaAdapter implements PerguntaTemplateVagaRepositorio {private final PerguntaTemplateVagaJpaRepository r;private final PerguntaTemplateVagaJpaMapper m;PerguntaTemplateVagaJpaAdapter(PerguntaTemplateVagaJpaRepository r,PerguntaTemplateVagaJpaMapper m){this.r=r;this.m=m;}public Optional<PerguntaTemplateVaga> buscarAtivaPorId(UUID id){return id==null?Optional.empty():r.findByIdAndExcluidoEmIsNull(id).map(m::paraDominio);}public List<PerguntaTemplateVaga> listarAtivasDoTemplate(UUID id){return r.findByTemplateVagaIdAndExcluidoEmIsNull(id).stream().map(m::paraDominio).collect(Collectors.toList());}public PerguntaTemplateVaga salvar(PerguntaTemplateVaga x){return m.paraDominio(r.save(m.paraEntidade(x)));}}
